const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let input = '';
rl.on('line', (line) => {
    input = line.trim();
});

rl.on('close', () => {
    const n = parseInt(input, 10);

    if (n === 2) {
        console.log("white");
        console.log("1 2");
    } else if (n % 2 === 1) {
        console.log("black");
    } else {
        // n is even and n >= 4
        console.log("white");
        console.log("1 2");
    }
});
